  "commands.catalog.canvas.save.arg.overwrite": "Ein vorhandenes Projekt ersetzen",
  "commands.catalog.canvas.preview.title": "Bild ansehen",
  "commands.catalog.canvas.preview.description": "Rendert das Bild reduziert als PNG (höchstens size Pixel an der langen Seite, standardmäßig 1024) und antwortet mit der Datei, damit du ansehen kannst, was du gemacht hast.",
  "commands.catalog.canvas.preview.arg.project": "Das .comp-Projekt (vollständiger Pfad oder ~/…); ohne Angabe das vordere Bild",
